CREATE OR REPLACE FUNCTION public.complete_onboarding(p_name text, p_avatar text, p_age integer, p_type text, p_bot_name text, p_description text, p_instructions text, p_look jsonb) RETURNS uuid LANGUAGE plpgsql SET search_path = public AS $$ DECLARE person public.profiles; bot_id uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; SELECT * INTO person FROM public.profiles WHERE id = auth.uid() FOR UPDATE; IF person.id IS NULL THEN RAISE EXCEPTION 'Profile unavailable'; END IF; IF person.onboarding_completed AND person.primary_bot_id IS NOT NULL THEN RETURN person.primary_bot_id; END IF; IF length(trim(p_name)) < 2 OR length(trim(p_name)) > 40 OR length(trim(p_bot_name)) < 1 OR length(trim(p_bot_name)) > 60 THEN RAISE EXCEPTION 'Invalid name'; END IF; IF length(coalesce(p_avatar,'')) > 500000 OR length(coalesce(p_description,'')) > 1000 OR length(coalesce(p_instructions,'')) > 10000 THEN RAISE EXCEPTION 'Input too large'; END IF; INSERT INTO public.bots(owner_id,name,description,instructions,category,look) VALUES(auth.uid(),trim(p_bot_name),p_description,p_instructions,'primary',coalesce(p_look,'{}'::jsonb)) RETURNING id INTO bot_id; UPDATE public.profiles SET display_name=trim(p_name), avatar_url=p_avatar, age=p_age, user_type=p_type, primary_bot_id=bot_id, onboarding_completed=true WHERE id=auth.uid(); RETURN bot_id; END $$;
REVOKE ALL ON FUNCTION public.complete_onboarding(text,text,integer,text,text,text,text,jsonb) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.complete_onboarding(text,text,integer,text,text,text,text,jsonb) TO authenticated;